 "content": "def transform(grid):
    """Encode counts of horizontal 3- and 2-bars in a 2x3 inventory."""
    counts = {3: 0, 2: 0}
    for row in grid:
        in_bar = False
        for value in row:
            if value in counts:
                if not in_bar:
                    counts[value] += 1
                in_bar = True
            else:
                in_bar = False
    cells = [3] * counts[3] + [2] * counts[2]
    cells = (cells + [0] * 6)[:6]
    return [cells[:3], cells[3:]]
